/* ── Shared ── */
function Tag({ label }) {
  return <span style={{ display:"inline-block", padding:"3px 10px", background:`${C.navyMid}18`, borderRadius:20, fontSize:12, color:C.navyMid, fontWeight:600, marginRight:5, marginBottom:5, fontFamily:FB }}>{label}</span>;
}

function Btn({ children, onClick, variant="primary", full, small }) {
  const v = {
    primary:      { background:C.green,   color:C.white,   border:"none" },
    navy:         { background:C.navy,    color:C.white,   border:"none" },
    outline:      { background:"transparent", color:C.navy, border:`2px solid ${C.navy}` },
    outlineW:     { background:"transparent", color:C.white, border:"2px solid rgba(255,255,255,0.55)" },
    outlineGreen: { background:"transparent", color:C.green, border:`2px solid ${C.green}` },
  };
  return (
    <button onClick={onClick} style={{ ...v[variant], display:"inline-flex", alignItems:"center", gap:8, padding:small?"9px 18px":"12px 26px", borderRadius:7, fontFamily:FH, fontWeight:700, fontSize:small?13:14, cursor:"pointer", letterSpacing:"0.02em", transition:"all 0.2s", width:full?"100%":undefined, justifyContent:full?"center":undefined }}
      onMouseEnter={e=>{e.currentTarget.style.opacity="0.85";e.currentTarget.style.transform="translateY(-1px)";}}
      onMouseLeave={e=>{e.currentTarget.style.opacity="1";e.currentTarget.style.transform="translateY(0)";}}
    >{children}</button>
  );
}

function SLabel({ text, light }) {
  return (
    <div style={{ display:"inline-flex", alignItems:"center", gap:8, marginBottom:10 }}>
      <div style={{ width:24, height:2, background:C.green }} />
      <span style={{ fontSize:11, fontWeight:700, letterSpacing:"0.14em", textTransform:"uppercase", color: light?"rgba(255,255,255,0.7)":C.green, fontFamily:FH }}>{text}</span>
      <div style={{ width:24, height:2, background:C.green }} />
    </div>
  );
}

function Section({ bg, children, className, style:st }) {
  return (
    <section style={{ background:bg||C.bg, width:"100%", ...st }}>
      <div style={{ maxWidth:1400, margin:"0 auto", padding:"72px 32px" }} className={className}>
        {children}
      </div>
    </section>
  );
}

/* ── Header ── */
function Header({ page, nav }) {
  const [scrolled, setScrolled] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  useEffect(()=>{
    const fn = ()=>setScrolled(window.scrollY>30);
    window.addEventListener("scroll",fn);
    return ()=>window.removeEventListener("scroll",fn);
  },[]);
  const NAV = [{label:"Home",id:"home"},{label:"Diensten",id:"diensten"},{label:"Over ons",id:"over-ons"},{label:"Projecten",id:"projecten"},{label:"Contact",id:"contact"}];
  return (
    <header style={{ position:"sticky", top:0, zIndex:200, width:"100%", background:scrolled?"rgba(13,31,60,0.97)":C.navyDk, backdropFilter:"blur(10px)", borderBottom:"1px solid rgba(255,255,255,0.07)", boxShadow:scrolled?"0 4px 24px rgba(0,0,0,0.3)":"none", transition:"all 0.3s" }}>
      <div style={{ maxWidth:1400, margin:"0 auto", padding:"0 32px", display:"flex", alignItems:"center", justifyContent:"space-between", height:76 }}>
        <button onClick={()=>nav("home")} style={{ border:"none", background:"none", cursor:"pointer", padding:0 }}>
          <img src={LOGO} alt="Hartog-Bos Duurzame Installaties" style={{ height:50, objectFit:"contain" }}/>
        </button>
        <nav className="desktop-nav">
          {NAV.map(n=>(
            <button key={n.id} onClick={()=>nav(n.id)} style={{ border:"none", borderBottom:page===n.id?`2px solid ${C.green}`:"2px solid transparent", background:"none", cursor:"pointer", padding:"8px 14px", borderRadius:"6px 6px 0 0", fontFamily:FH, fontSize:13, fontWeight:700, color:page===n.id?C.white:"rgba(255,255,255,0.6)", letterSpacing:"0.03em", transition:"all 0.15s" }}
              onMouseEnter={e=>e.currentTarget.style.color="white"}
              onMouseLeave={e=>{if(page!==n.id)e.currentTarget.style.color="rgba(255,255,255,0.6)";}}
            >{n.label}</button>
          ))}
        </nav>
        <div className="desktop-right">
          <a href="tel:0612345678" style={{ display:"flex", alignItems:"center", gap:7, fontSize:13, fontWeight:700, color:"rgba(255,255,255,0.85)", textDecoration:"none", fontFamily:FH }}>
            <Phone size={14} color={C.green}/> 06 12 34 56 78
          </a>
          <Btn onClick={()=>nav("offerte")} variant="primary" small>Offerte aanvragen</Btn>
        </div>
        <button className="mobile-nav" onClick={()=>setMobileOpen(!mobileOpen)} style={{ border:"none", background:"none", cursor:"pointer", color:C.white, padding:8 }}>
          {mobileOpen ? <X size={24}/> : <Menu size={24}/>}
        </button>
      </div>
      {mobileOpen && (
        <div style={{ background:C.navyDk, borderTop:"1px solid rgba(255,255,255,0.08)", padding:"16px 32px 24px" }}>
          {NAV.map(n=>(
            <button key={n.id} onClick={()=>{nav(n.id);setMobileOpen(false);}} style={{ display:"block", width:"100%", textAlign:"left", border:"none", borderBottom:`1px solid rgba(255,255,255,0.07)`, background:"none", cursor:"pointer", padding:"14px 0", fontFamily:FH, fontSize:15, fontWeight:700, color:page===n.id?C.green:"rgba(255,255,255,0.75)" }}>
              {n.label}
            </button>
          ))}
          <div style={{ marginTop:20, display:"flex", flexDirection:"column", gap:12 }}>
            <a href="tel:0612345678" style={{ display:"flex", alignItems:"center", gap:8, fontSize:14, fontWeight:700, color:"rgba(255,255,255,0.85)", textDecoration:"none", fontFamily:FH }}>
              <Phone size={15} color={C.green}/> 06 12 34 56 78
            </a>
            <Btn onClick={()=>{nav("offerte");setMobileOpen(false);}} variant="primary" full>Offerte aanvragen</Btn>
          </div>
        </div>
      )}
    </header>
  );
}

