/* ── Contact ── */
function ContactPage() {
  const [form, setForm] = useState({naam:"",tel:"",bericht:""});
  const [sent, setSent] = useState(false);
  const [error, setError] = useState(false);
  const f = k=>({value:form[k], onChange:e=>setForm({...form,[k]:e.target.value})});

  const handleSubmit = () => {
    if (!form.naam || !form.tel) return;
    fetch("/", {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        "form-name": "contact",
        naam: form.naam,
        telefoon: form.tel,
        bericht: form.bericht,
      }).toString(),
    })
    .then(() => setSent(true))
    .catch(() => setError(true));
  };
  return (
    <>
      <section style={{ background:`linear-gradient(160deg, ${C.navyDk} 0%, ${C.navy} 60%, ${C.navyMid} 100%)`, padding:"80px 32px 64px", width:"100%" }} className="page-hero">
        <div style={{ maxWidth:760, margin:"0 auto", textAlign:"center" }}>
          <SLabel text="Neem contact op" light/>
          <h1 style={{ fontFamily:FH, fontSize:"clamp(28px,5vw,50px)", fontWeight:700, color:C.white, margin:"12px 0 16px" }}>Contact</h1>
          <p style={{ fontSize:17, color:"rgba(255,255,255,0.7)", lineHeight:1.75, fontFamily:FB }}>Heeft u een vraag of wilt u een afspraak maken? Wij horen graag van u.</p>
        </div>
      </section>
      <Section bg={C.bg}>
        <div className="contact-grid" style={{ display:"grid", gridTemplateColumns:"1fr 1.6fr", gap:56 }}>
          <div>
            <h2 style={{ fontFamily:FH, fontSize:24, fontWeight:700, color:C.navy, marginBottom:32 }}>Contactgegevens</h2>
            {[{Icon:Phone,l:"Telefoon",v:"06 12 34 56 78",href:"tel:0612345678"},{Icon:Mail,l:"E-mail",v:"info@hartog-bosinstallaties.nl",href:"mailto:info@hartog-bosinstallaties.nl"},{Icon:MapPin,l:"Werkgebied",v:"Nijmegen en omgeving"},{Icon:Clock,l:"Bereikbaar",v:"Ma - Vr: 08:00 - 17:00"}].map(({Icon,l,v,href},i)=>(
              <div key={i} style={{ display:"flex", gap:16, marginBottom:24 }}>
                <div style={{ width:46, height:46, borderRadius:10, background:`${C.green}18`, display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>
                  <Icon size={20} color={C.green}/>
                </div>
                <div>
                  <div style={{ fontSize:11, fontWeight:700, color:C.gray, textTransform:"uppercase", letterSpacing:"0.07em", marginBottom:4, fontFamily:FH }}>{l}</div>
                  {href ? <a href={href} style={{ fontSize:15, fontWeight:700, color:C.navy, fontFamily:FH, textDecoration:"none" }}>{v}</a>
                        : <div style={{ fontSize:15, fontWeight:700, color:C.navy, fontFamily:FH }}>{v}</div>}
                </div>
              </div>
            ))}
          </div>
          <div style={{ background:C.white, borderRadius:16, padding:36, border:`1px solid ${C.border}`, boxShadow:"0 4px 24px rgba(27,58,107,0.07)" }}>
            <h3 style={{ fontFamily:FH, fontSize:20, fontWeight:700, color:C.navy, marginBottom:26 }}>Stuur ons een bericht</h3>
            {sent ? (
              <div style={{ textAlign:"center", padding:"48px 0" }}>
                <CheckCircle size={52} color={C.green}/>
                <p style={{ fontSize:16, fontWeight:700, color:C.navy, marginTop:16, fontFamily:FH }}>Bedankt! Wij nemen snel contact met u op.</p>
              </div>
            ) : (
              <>
                <FormField label="Naam" placeholder="Uw volledige naam" {...f("naam")}/>
                <FormField label="Telefoonnummer" type="tel" placeholder="Uw telefoonnummer" {...f("tel")}/>
                <FormField label="Bericht" rows={5} placeholder="Hoe kunnen wij u helpen?" {...f("bericht")}/>
                {error && <p style={{color:"red",fontSize:13,marginBottom:12,fontFamily:FB}}>Er ging iets mis. Probeer het opnieuw of bel ons direct.</p>}
                <Btn onClick={handleSubmit} variant="primary" full>Verstuur bericht <ArrowRight size={15}/></Btn>
              </>
            )}
          </div>
        </div>
      </Section>
    </>
  );
}

